package com.codelink.app;
import android.app.*;import android.content.*;import android.hardware.Camera;import android.os.*;import android.view.*;import android.widget.*;import com.google.zxing.*;import com.google.zxing.common.HybridBinarizer;
@SuppressWarnings("deprecation") public final class ScanActivity extends Activity implements SurfaceHolder.Callback,Camera.PreviewCallback{
 private Camera camera;private boolean busy,finished;private long last;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(128);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff192d27);TextView text=new TextView(this);text.setText("扫描电脑 Code Link 的连接二维码");text.setTextColor(-1);text.setPadding(22,30,22,30);text.setTextSize(19);root.addView(text);SurfaceView surface=new SurfaceView(this);root.addView(surface,new LinearLayout.LayoutParams(-1,0,1));surface.getHolder().addCallback(this);setContentView(root);}
 public void surfaceCreated(SurfaceHolder holder){try{camera=Camera.open();camera.setDisplayOrientation(90);Camera.Parameters p=camera.getParameters();if(p.getSupportedFocusModes().contains(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE))p.setFocusMode(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE);camera.setParameters(p);camera.setPreviewDisplay(holder);camera.setPreviewCallback(this);camera.startPreview();}catch(Exception e){Toast.makeText(this,"相机不可用："+e.getMessage(),1).show();finish();}}
 public void surfaceChanged(SurfaceHolder h,int f,int w,int he){}public void surfaceDestroyed(SurfaceHolder h){release();}private void release(){if(camera!=null){camera.setPreviewCallback(null);camera.stopPreview();camera.release();camera=null;}}
 public void onPreviewFrame(byte[] bytes,Camera c){if(busy||finished||System.currentTimeMillis()-last<250)return;busy=true;last=System.currentTimeMillis();Camera.Size size=c.getParameters().getPreviewSize();byte[] copy=bytes.clone();new Thread(()->{try{PlanarYUVLuminanceSource source=new PlanarYUVLuminanceSource(copy,size.width,size.height,0,0,size.width,size.height,false);Result result=new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(source)));if(result.getText().startsWith("codelink:")){finished=true;runOnUiThread(()->{setResult(RESULT_OK,new Intent().putExtra("invite",result.getText()));finish();});}}catch(Exception ignored){}finally{busy=false;}}).start();}
 protected void onDestroy(){release();super.onDestroy();}
}
